  "attack_progression": [
    {"step": 1, "tactic": "Certificate store enumeration with HasPrivateKey filter", "technique": "T1649", "what_happened": "At 2032-03-22 19:18:08 UTC on WS-ENG-58, AMSI EID 4104 captured a powershell.exe scriptblock iterating through X509Store('My','CA','Root') across CurrentUser + LocalMachine, reading $cert.HasPrivateKey on each certificate. Rule 100600 triggered.", "chain_reason": "Systematic enumeration of every certificate store while filtering on HasPrivateKey is the precondition step of T1649 — the attacker identifies which certs can be exported with their private key."},
    {"step": 2, "tactic": "Export-PfxCertificate or certutil -exportpfx", "technique": "T1649", "what_happened": "At 2032-03-22 19:18:25, Sysmon EID 1 captured either powershell.exe running 'Export-PfxCertificate -Cert Cert:\\CurrentUser\\My\\<thumbprint> -FilePath %TEMP%\\stolen_cert_191808.pfx -Password (ConvertTo-SecureString \"P@ssw0rd!STOLEN\" -AsPlainText -Force)' AND/OR certutil.exe with -exportpfx flag pointing to %TEMP%. Rule 100600 fired with high confidence.", "chain_reason": "Export-PfxCertificate AND certutil -exportpfx are the two canonical Windows commands to export a certificate WITH ITS PRIVATE KEY into a PFX/PKCS12 file. The PFX is a portable, passwordless authentication credential."},
    {"step": 3, "tactic": "PFX file written to user temp directory", "technique": "T1649", "what_happened": "At 2032-03-22 19:18:26, Sysmon EID 11 captured creation of C:\\Users\\t.brandeis\\AppData\\Local\\Temp\\p145_cert_191808\\stolen_cert_191808.pfx (2812 bytes binary, PKCS12 magic bytes 0x30 0x82). Rule 100601 triggered.", "chain_reason": "A *.pfx file in %TEMP% (NOT in C:\\ProgramData\\cert or any other approved certificate store path) is the canonical T1649 forensic artefact — corp cert management software writes to managed paths, never to user temp."},
    {"step": 4, "tactic": "Operator-staged file naming pattern", "technique": "T1649", "what_happened": "The exported PFX filename is literally 'stolen_cert_<timestamp>.pfx' and the PFX password embedded in the scriptblock is 'P@ssw0rd!STOLEN'. The 'STOLEN' substring in both the filename and password is operator-named attacker intent.", "chain_reason": "Operator-named 'stolen_cert' filename + 'STOLEN' in the password is unambiguous intent — no corp tool would name an artefact this way."}
  ],
